-- Cleanup E2E test junk + seed pending review content (demo schema).
-- Safe to re-run: inserts use on conflict do nothing.

-- ── E2E cleanup ───────────────────────────────────────

delete from demo.notifications
where entity_id in (
  select id from demo.trips where name like 'E2E %'
  union select id from demo.places where name like 'E2E %'
  union select id from demo.trails where name like 'E2E %'
);

delete from demo.favorites
where entity_id in (
  select id from demo.trips where name like 'E2E %'
  union select id from demo.places where name like 'E2E %'
  union select id from demo.trails where name like 'E2E %'
);

delete from demo.ratings
where entity_id in (
  select id from demo.trips where name like 'E2E %'
  union select id from demo.places where name like 'E2E %'
  union select id from demo.trails where name like 'E2E %'
);

delete from demo.trip_stations
where trip_id in (select id from demo.trips where name like 'E2E %');

delete from demo.trips where name like 'E2E %';
delete from demo.places where name like 'E2E %';
delete from demo.trails where name like 'E2E %';

